// mobile/main.js
import React from "react";
import { Routes, Route } from "react-router-dom";
import Home from "./pages/Home";

function MobileApp() {
  return (
    <div className="mobile-only-styles">
      <Routes>
        {/* Crucial: Use index or path="/" 
           This matches 'localhost:3000/mobile' 
        */}
        <Route index element={<Home />} />

        {/* Matches 'localhost:3000/mobile/settings' */}
        <Route path="settings" element={<div>Mobile Settings</div>} />
      </Routes>
    </div>
  );
}
export default MobileApp;
